<?php $title='Usuários e planos'; ?>
<section class="dashboard-section"><form class="filter-bar" method="get" action="<?=url('/admin/users')?>"><input name="q" value="<?=e($q)?>" placeholder="Buscar nome ou e-mail"><button class="btn btn-primary">Buscar</button></form><div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Plano</th><th>Status</th><th>Alterar</th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><b><?=e($item['name'])?></b><small><?=e($item['email'])?></small></td><td><?=e($item['role_name'])?></td><td><?=e($item['plan_name']?:'-')?></td><td><?=e($item['status'])?></td><td><form class="inline-form" method="post" action="<?=url('/admin/users/'.$item['id'])?>"><?=csrf_field()?><select name="plan_id"><?php foreach($plans as $plan):?><option value="<?=e($plan['id'])?>" <?=selected($item['plan_id'],$plan['id'])?>><?=e($plan['name'])?></option><?php endforeach;?></select><select name="status"><option <?=selected($item['status'],'ACTIVE')?>>ACTIVE</option><option <?=selected($item['status'],'PENDING')?>>PENDING</option><option <?=selected($item['status'],'SUSPENDED')?>>SUSPENDED</option></select><button class="btn btn-soft">Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
